a0 = [4, 7, 1, 8, 3]
def bubble_pass(a):
    a = a[:]
    for j in range(len(a) - 1):
        if a[j] > a[j + 1]: a[j], a[j + 1] = a[j + 1], a[j]
    return a
def selection(a, iters):
    a = a[:]
    for i in range(iters):
        m = min(range(i, len(a)), key=lambda k: a[k]); a[i], a[m] = a[m], a[i]
    return a
def insertion(a, iters):
    a = a[:]; shifts = 0
    for i in range(1, iters + 1):
        key = a[i]; j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]; j -= 1; shifts += 1
        a[j + 1] = key
    return a, shifts
inversions = sum(a0[i] > a0[j] for i in range(5) for j in range(i + 1, 5))
truth = {
    'A': bubble_pass(a0) == [4, 1, 7, 3, 8],
